  { titulo: 'Importar CSV', rota: '/importar', texto: 'Traga o extrato do banco em CSV: você confere as linhas antes de importar e duplicatas são sinalizadas.' },
  { titulo: 'Dashboard', rota: '/', texto: 'O Dashboard resume saldos, receitas, despesas do mês e a projeção dos próximos meses.' },
